style.css:
@-moz-document domain("drive.google.com") {
/* fundo geral */
body {
    background-color: #fff5f7 !important;
}

/* sidebar */
div[role="navigation"] {
    background-color: #ffeef2 !important;
}

/* arquivos */
div[role="main"] {
    background-color: #fff0f5 !important;
    border-radius: 12px;
}

/* arquivos (cards) */
div[role="row"] {
    border-radius: 10px;
}

/* hover */
div[role="row"]:hover {
    background-color: rgba(255, 182, 193, 0.2) !important;
}

/* textos */
span {
    color: #000 !important;
}
}
